// Summarise the SEO Agent callback (the full payload stays in this execution for inspection)
const b = $input.first().json.body || {};
const size = (s) => s ? Math.round(String(s).length * 0.75 / 1024) + ' KB' : null;
return [{ json: { received_at: new Date().toISOString(), status: b.status, request_id: b.request_id, execution_id: b.execution_id, keyword: b.keyword, domain: b.domain, verdict: b.verdict, score: b.score, error: b.error || null, qa_summary: b.qa_summary || null, pdf_kb: b.pdf ? size(b.pdf.data) : null, doc_kb: b.file ? size(b.file.data) : null, run_ledger: b.run_ledger || null, keys: Object.keys(b), payload: b } }];
